let lang='fa', model='tipper', view='photo', photoIndex=0, featureIndex=0, motionFrame=0, motionStart=0, factoryStep=0;
const prefersReduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
const t=k=>text[lang][k] || k;
const fmt=n=>String(n).padStart(2,'0');
const seriesLabel=id=>lang==='en'?models[id].series:`${t('brandWord')} / ${t('option'+id[0].toUpperCase()+id.slice(1))}`;
function translate(){
 document.documentElement.lang=lang;document.documentElement.dir=rtl()?'rtl':'ltr';
 $$('[data-i]').forEach(el=>{const val=t(el.dataset.i);if(typeof val==='string')el.innerHTML=val;});
 $$('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===lang)));$('#lang-current').textContent=lang.toUpperCase();
 $('#studio-image').alt=t('studioAlt');$('#factory-video').setAttribute('aria-label',t('filmLabel'));document.title=page==='home'?t('pageTitle'):`${t({products:'navProducts',tools:'navPlanner',factory:'navFactory',gallery:'navGallery',about:'navAbout'}[page])} — MARAL`;
 $('#form-cargo').placeholder=t('cargoPh');$('#form-notes').placeholder=t('notesPh');
 renderModel();renderCompare();renderStep();updateFilmButton();setView(view);renderTools();
}
function renderModel(){
 const m=models[model];
 $$('.mission-item').forEach(b=>{const active=b.dataset.model===model;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});
 $('#product-series').textContent=seriesLabel(model);$('#stage-model').textContent=seriesLabel(model);
 $('#product-title').innerHTML=m.title[lang];$('#product-description').textContent=m.desc[lang];
 $('#spec-main').textContent=m.main;$('#spec-main-label').textContent=t(m.label);$('#product-note').textContent=m.note[lang];$('#product-source').href=m.source;
 $('#feature-list').replaceChildren();m.features.forEach((f,i)=>{const b=document.createElement('button');b.innerHTML=`<span>${f[lang]}</span><span>＋</span>`;b.classList.toggle('active',i===featureIndex);b.setAttribute('aria-pressed',String(i===featureIndex));b.addEventListener('click',()=>showFeature(i));$('#feature-list').append(b);});
 $('#tab-tech').disabled=model!=='tipper';$('#tab-unload').disabled=model!=='tipper';
 renderPhoto();showFeature(featureIndex);renderSummary();renderProductVideo();
}
function selectModel(id,scroll=false){
 if(!models[id])return;stopMotion();model=id;photoIndex=0;featureIndex=0;setView('photo');renderModel();
 state.model=id;state.explored=true;saveState();setPlanModel(id);renderJourney();
 if(scroll)$('#studio').scrollIntoView({behavior:prefersReduced?'instant':'smooth',block:'start'});
}
function renderPhoto(){
 const m=models[model];photoIndex=(photoIndex+m.photos.length)%m.photos.length;
 $('#studio-image').src=m.photos[photoIndex];$('#studio-image').style.objectFit=model==='reefer'&&m.photos[0].endsWith('.png')?'contain':'cover';
 $('#photo-count').textContent=`${fmt(photoIndex+1)} / ${fmt(m.photos.length)}`;
 $('#photo-caption').textContent=t('photo');$('#photo-prev').disabled=$('#photo-next').disabled=m.photos.length<2;
}
