 if(next!=='photo'&&model!=='tipper')next='photo';if(next!=='unload')stopMotion();view=next;
 $$('[data-view]').forEach(b=>{const active=b.dataset.view===view;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;});
