 $('.feature-index').textContent=lang==='en'?f.code:f.code.split(' / ')[0];$('#feature-title').textContent=f[lang];$('#feature-description').textContent=f.detail[lang];
 $$('#feature-list button').forEach((b,n)=>{b.classList.toggle('active',n===featureIndex);b.setAttribute('aria-pressed',String(n===featureIndex));});
 $$('.hotspot').forEach(h=>{h.classList.toggle('selected',h.dataset.feature===String(featureIndex));h.querySelector('circle').setAttribute('fill',h.dataset.feature===String(featureIndex)?'#f5a300':'#0c2240');});
