function wheel(x,y,prefix){return `<g transform="translate(${x} ${y})"><circle r="35" fill="#151f2c"/><circle r="30" fill="#263242" stroke="#5e6d7d" stroke-width="1"/><circle r="20" fill="url(#${prefix}-rim)" stroke="#c4cbd1" stroke-width="3"/><circle r="10" fill="#697585"/><circle r="5" fill="#263141"/>${Array.from({length:8},(_,i)=>`<circle cx="${Math.cos(i*Math.PI/4)*14}" cy="${Math.sin(i*Math.PI/4)*14}" r="2" fill="#253243"/>`).join('')}</g>`;}
function schematic(prefix,unload=false){
 const ribs=Array.from({length:9},(_,i)=>`<path d="M${224+i*54} 115 l-9 82" stroke="#c98a00" stroke-width="5"/>`).join('');
 const beams=Array.from({length:11},(_,i)=>`<path d="M${190+i*51} 207 l14 -14 v18" fill="none" stroke="#687c8d" stroke-width="3"/>`).join('');
 const dots=[{x:365,y:220,i:0},{x:643,y:269,i:1},{x:235,y:187,i:2}].map(a=>`<g class="hotspot" tabindex="0" role="button" aria-label="${['Chassis','Axles','Hydraulics'][a.i]}" data-feature="${a.i}" transform="translate(${a.x} ${a.y})"><circle r="17" fill="#0c2240" stroke="#fff" stroke-width="2"/><text text-anchor="middle" dominant-baseline="central" fill="white" font-family="Arial" font-size="15">+</text></g>`).join('');
 return `<svg viewBox="0 0 900 355" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Illustrative Maral tipper structure"><defs><linearGradient id="${prefix}-body" x1="0" y1="0" x2="0.2" y2="1"><stop stop-color="#ffd84a"/><stop offset=".7" stop-color="#f5b800"/><stop offset="1" stop-color="#d99a00"/></linearGradient><radialGradient id="${prefix}-rim"><stop stop-color="#c9d0d3"/><stop offset="1" stop-color="#71818f"/></radialGradient><clipPath id="${prefix}-clip"><rect class="body-clip" width="${unload?900:450}" height="355"/></clipPath></defs><ellipse cx="482" cy="311" rx="332" ry="12" fill="#1e304516"/><path d="M90 310 H835" stroke="#9faab3" stroke-width="1"/><path d="M179 223 H752 L764 238 H183 Z" fill="#304254"/><path d="M180 210 L752 210 V225 H180Z" fill="#50687a"/>${beams}<path d="M254 227 v61 h-12 v-61 M240 287 h33" stroke="#566a7b" stroke-width="5" fill="none"/><path d="M759 238 v39 h-30" fill="none" stroke="#536d80" stroke-width="7"/><path d="M558 245 H726" stroke="#617686" stroke-width="7"/>${[574,641,708].map(x=>wheel(x,269,prefix)).join('')}<path d="M556 224 h173 v15 H556Z" fill="#40576a"/><g class="hydraulic-cylinder"><path class="cylinder-base" d="M286 217 L204 175" stroke="#354f66" stroke-width="14" stroke-linecap="round"/><path class="cylinder-rod" d="M260 204 L204 175" stroke="#c0cbd2" stroke-width="7" stroke-linecap="round"/></g>${unload?'<g class="spill" opacity="0"><path d="M756 206 C772 238 778 270 774 306" stroke="#c9a36b" stroke-width="18" stroke-linecap="round" fill="none"/><path d="M748 210 C760 246 762 280 758 306" stroke="#a8875a" stroke-width="8" stroke-linecap="round" fill="none" stroke-dasharray="6 9"/><ellipse class="heap" cx="790" cy="306" rx="46" ry="12" fill="#b8956a"/></g>':''}<g class="svg-body" clip-path="${unload?'none':`url(#${prefix}-clip)`}"><path d="M171 109 L745 109 L763 123 L189 123Z" fill="#ffe27a"/><path d="M171 109 L190 123 L215 204 L197 190Z" fill="#a87400"/><path d="M190 123 H763 L745 205 H215Z" fill="url(#${prefix}-body)" stroke="#b07c00" stroke-width="2"/>${ribs}<path d="M195 123 H759" stroke="#ffe9a0" stroke-width="3"/><path d="M214 204 H746" stroke="#9a6a00" stroke-width="5"/><text x="461" y="175" text-anchor="middle" font-family="Arial" font-size="32" font-weight="bold" letter-spacing="14" fill="#13457a">MARAL</text><path d="M177 100 L183 111" stroke="#6c7a87" stroke-width="3"/><path d="M201 129 L184 204" stroke="#34485c" stroke-width="3"/><path d="M746 126 L728 200" stroke="#a87400" stroke-width="3"/></g>${unload?'':`<g class="scan-line"><path d="M450 75 V303" stroke="#f5a300" stroke-width="2" stroke-dasharray="4 3"/><circle cx="450" cy="75" r="4" fill="#f5a300"/><text x="460" y="80" fill="#f5a300" font-family="Arial" font-size="10" data-i="svgReveal"></text></g>${dots}`}<path d="M183 330 H751 M183 325 v10 M751 325 v10" stroke="#8798a7"/><text x="467" y="349" text-anchor="middle" fill="#7d8c9a" font-family="Arial" font-size="9" letter-spacing="2" data-i="${unload?'svgNoteMotion':'svgNoteTech'}"></text></svg>`;
}
