const videos={
 aparat:[{id:'e9277u7',time:60,fa:'تریلی چادری سه‌محور با سقف و دیواره کشویی',en:'Three-axle curtainsider with sliding roof and walls'},{id:'s29tl7k',time:51,fa:'تریلر چادری چهارمحور برای بازار روسیه',en:'Four-axle curtainsider for the Russian market'},{id:'xpqzf04',time:91,fa:'تفاوت تانکر LPG مارال با تانکر معمولی',en:'Maral LPG tanker versus a standard tanker'},{id:'r945e1t',time:113,fa:'فرآیند کاتافورز؛ پوشش رنگی قطعات',en:'Cataphoresis: coating trailer and vehicle parts'},{id:'a49vz91',time:69,fa:'افتتاح خط رنگ E.D محورسازان چی‌چیست',en:'Chichest Axle opens its E.D paint line'},{id:'o28y1s1',time:112,fa:'روز ملی کیفیت در مارال',en:'National Quality Day at Maral'}],
 youtube:[{id:'AOYaoPEnOAs',fa:'۲۱ سال با مارال',en:'21 years with Maral'},{id:'4zJbC1JZl_Q',fa:'تجربه مشتریان مارال',en:'Maral customer stories'},{id:'NJ20xIWVph8',model:'fuel',fa:'تانکر سوخت مارال',en:'Maral fuel tanker'},{id:'9DzAeEtdKak',model:'reefer',fa:'تریلر یخچالی مارال',en:'Maral refrigerated trailer'},{id:'8couwnXfFOM',fa:'تریلی لبه‌دار مارال',en:'Maral side-wall trailer'},{id:'3rsm9vk8TAM',fa:'مارال × مهدی دلانگیزان، قسمت ۱',en:'Maral Trailer × Mehdi Delangizan, EP1'}]
};
let channel=null,videoIndex=0;
const currentChannel=()=>channel||(lang==='fa'?'aparat':'youtube');
const poster=(ch,v)=>`assets/video/${ch==='aparat'?'ap':'yt'}-${v.id}.jpg`;
const duration=s=>s?`${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`:'';
function renderMedia(){
 const ch=currentChannel(),list=videos[ch];videoIndex=Math.min(videoIndex,list.length-1);const v=list[videoIndex];
 $$('[data-channel]').forEach(b=>{const active=b.dataset.channel===ch;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;});
 const player=$('#media-player');$('iframe',player)?.remove();player.classList.remove('playing');
 $('#media-poster').src=poster(ch,v);$('#media-now').textContent=v[lang];$('#media-source').textContent=ch==='aparat'?`${t('chAparat')} · maraltrailer1`:'YouTube · @maraltrailer';
 const ol=$('#media-list');ol.replaceChildren();
 list.forEach((item,i)=>{const li=document.createElement('li'),b=document.createElement('button');b.type='button';b.className='media-item'+(i===videoIndex?' active':'');b.setAttribute('aria-current',String(i===videoIndex));
  const img=document.createElement('img');img.src=poster(ch,item);img.alt='';img.loading='lazy';const span=document.createElement('span');span.textContent=item[lang];const small=document.createElement('small');small.textContent=duration(item.time)||(ch==='aparat'?'Aparat':'YouTube');
  b.append(img,span,small);b.addEventListener('click',()=>{videoIndex=i;renderMedia();playVideo();});li.append(b);ol.append(li);});
}
function playVideo(){
 const ch=currentChannel(),v=videos[ch][videoIndex],player=$('#media-player');$('iframe',player)?.remove();
 const f=document.createElement('iframe');f.src=ch==='aparat'?`https://www.aparat.com/video/video/embed/videohash/${v.id}/vt/frame`:`https://www.youtube-nocookie.com/embed/${v.id}?autoplay=1&rel=0`;
 f.title=v[lang];f.allow='autoplay; encrypted-media; picture-in-picture; fullscreen';f.allowFullscreen=true;player.append(f);player.classList.add('playing');
 const fv=$('#factory-video');if(has('#factory-video')&&!fv.paused)fv.pause();
}
function renderProductVideo(){const has=videos.youtube.some(v=>v.model===model);$('#product-video').hidden=!has;}
$$('[data-channel]').forEach(b=>b.addEventListener('click',()=>{channel=b.dataset.channel;videoIndex=0;renderMedia();}));
$('.media-switch').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const next=$('[data-channel][aria-selected=false]');channel=next.dataset.channel;videoIndex=0;renderMedia();next.focus();});
$('#media-play').addEventListener('click',playVideo);
function openTV(spec,autoplay=true){
 const [ch,id]=(spec||'').split(':');if(videos[ch]){channel=ch;videoIndex=Math.max(0,videos[ch].findIndex(v=>v.id===id));}
 renderMedia();openDialog('tv-dialog');if(spec&&autoplay)playVideo();
}
$$('.tv-open').forEach(b=>b.addEventListener('click',()=>openTV()));
$('#tv-dialog').addEventListener('close',()=>renderMedia());
