/* Engineering stage full view: native fullscreen where available, a fixed overlay otherwise */
function stageFullState(on){$('#stage-full').setAttribute('aria-pressed',String(on));$('#stage-full span').textContent=t(on?'exitView':'fullView');document.body.classList.toggle('stage-is-full',on);}
$('#stage-full').addEventListener('click',()=>{const st=$('.product-stage');
 if(document.fullscreenElement){document.exitFullscreen();return;}
 if(st.classList.contains('stage-full')){st.classList.remove('stage-full');stageFullState(false);return;}
 if(st.requestFullscreen)st.requestFullscreen().then(()=>stageFullState(true)).catch(()=>{st.classList.add('stage-full');stageFullState(true);});
 else{st.classList.add('stage-full');stageFullState(true);}});
document.addEventListener('fullscreenchange',()=>stageFullState(!!document.fullscreenElement));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&has('.stage-full')){$('.stage-full').classList.remove('stage-full');stageFullState(false);}});
/* About Maral: scroll-driven story, eight chapters pinned in one sticky stage */
Object.assign(text.fa,{storyBrand:'داستان مارال',st0e:'۱۳۶۸ · ارومیه',st0t:'همه‌چیز از زمینی<br>۶٬۰۰۰ متری شروع شد.',st0d:'رضا رستمی مارال را در زمینی ۶٬۰۰۰ متری در ارومیه راه انداخت. همان کارگاه امروز بزرگ‌ترین کارخانه تریلرسازی ایران است؛ در کیلومتر ۱۰ جاده ارومیه به مهاباد.',st0v:'بزرگ‌ترین کارخانه تریلر ایران',st1e:'آدم‌ها',st1t:'یک کارخانه،<br>هزاران معیشت.',st1d:'۹۰۰ نفر مستقیم در مارال کار می‌کنند و بیش از ۵٬۰۰۰ شغل غیرمستقیم به این زنجیره وابسته است؛ از تأمین‌کننده فولاد تا راننده‌ای که با تریلر مارال کار می‌کند.',st1a:'شغل مستقیم',st1b:'شغل غیرمستقیم',st2e:'زنجیره یکپارچه',st2t:'چهار شرکت،<br>یک تریلر کامل.',st2d:'از محور تا قطعه یدکی و خدمات، هر حلقه درون گروه است. ظرفیت سالانه: بیش از ۵٬۰۰۰ تریلر و صدها نوع قطعه.',st2a:'تریلر · ارومیه',st2b:'محور و قطعات محور · محورسازان چی‌چیست',st2c:'لوازم جانبی و قطعات یدکی · مارال یدک',st2d2:'خدمات فنی و پس از فروش · تهران',st3e:'مهندسی',st3t:'اول در سه‌بعد،<br>بعد در فولاد.',st3d:'هر محصول ابتدا سه‌بعدی طراحی می‌شود، با قطعات برندهای معتبر اروپایی ساخته می‌شود و پیش از تحویل از سخت‌ترین آزمون‌های کیفی می‌گذرد.',st4e:'کیفیت',st4t:'کیفیت شعار نیست؛<br>گواهی‌نامه است.',st4d:'۱۷ استاندارد ملی، استاندارد جهانی ADR برای حمل کالای قابل اشتعال و ISO 9001، 10002، 10004 و 14001؛ همراه با عنوان‌های «صادرکننده نمونه ملی» و «واحد صنعتی نمونه».',st4a:'استاندارد ملی',st4b:'کالای قابل اشتعال',st4c:'مدیریت کیفیت',st4f:'رضایت مشتری',st4g:'پایش رضایت',st4h:'مدیریت محیط زیست',st4i:'صادرکننده نمونه ملی',st4j:'واحد صنعتی نمونه',st5e:'فراتر از تریلر',st5t:'بزرگ‌ترین سازنده<br>تانکر گاز مایع منطقه.',st5d:'با خط تولید تازه تانکرهای گاز مایع، مارال بزرگ‌ترین سازنده این محصول در منطقه و آسیا شده است؛ و با بازسازی اتوبوس شهری و تولید مینی‌بوس به تولید ملی کمک می‌کند.',st5v:'ویدیوی تانکر LPG',st5s:'بازسازی اتوبوس شهری · تولید مینی‌بوس',st6e:'صادرات',st6t:'از ارومیه<br>به سه قاره.',st6d:'محصولات مارال به کشورهای اروپایی، آسیایی و خاورمیانه صادر می‌شوند؛ از جمله تریلر چادری چهارمحور که برای بازار روسیه ساخته شده است.',st7e:'تعهد',st7t:'۱۰۰٬۰۰۰ کیلومتر<br>خیال راحت.',st7d:'گارانتی ۱۰۰٬۰۰۰ کیلومتر یا ۱۲ ماه، بیش از ۴۰ مرکز خدمات مجاز و یک هدف روشن: پیشروی تریلر و قطعات تریلر در خاورمیانه.',st7c:'تریلر بعدی‌ام را انتخاب کنم <span>↗</span>',st7g:'یا ۱۲ ماه گارانتی',storyNote:'بر اساس صفحه «درباره ما»ی مارال؛ به‌روزشده به ۳۷ سال. تعداد مراکز خدمات در منابع مارال ۲۰+ و ۴۰+ آمده و باید تأیید شود.',g2Name:'محورسازان چی‌چیست'});
Object.assign(text.en,{storyBrand:'THE MARAL STORY',st0e:'1989 · URMIA',st0t:'It all started<br>on 6,000 m².',st0d:'Reza Rostami started Maral on a 6,000-square-metre plot in Urmia. That workshop is now Iran’s largest trailer plant, at kilometre 10 on the Urmia–Mahabad road.',st0v:'Iran’s largest trailer plant',st1e:'PEOPLE',st1t:'One plant.<br>Thousands of livelihoods.',st1d:'900 people work directly at Maral and more than 5,000 indirect jobs depend on its chain, from steel suppliers to the drivers who earn a living with a Maral trailer.',st1a:'direct jobs',st1b:'indirect jobs',st2e:'INTEGRATED CHAIN',st2t:'Four companies.<br>One complete trailer.',st2d:'From axles to spare parts and service, every link sits inside the group, with capacity for 5,000+ trailers and hundreds of component types a year.',st2a:'Trailers · Urmia',st2b:'Axles & axle parts · Mehvarsazan Chichest',st2c:'Accessories & spare parts · Maral Yadak',st2d2:'Technical & aftersales service · Tehran',st3e:'ENGINEERING',st3t:'First in 3D.<br>Then in steel.',st3d:'Every product is designed in 3D, built with components from leading European brands and put through rigorous quality tests before delivery.',st4e:'QUALITY',st4t:'Quality isn’t a slogan.<br>It’s certified.',st4d:'17 national standards, the global ADR standard for flammable goods, and ISO 9001, 10002, 10004 and 14001, alongside the titles Exemplary National Exporter and Exemplary Industrial Unit.',st4a:'national standards',st4b:'flammable goods',st4c:'quality management',st4f:'customer satisfaction',st4g:'satisfaction monitoring',st4h:'environmental management',st4i:'Exemplary National Exporter',st4j:'Exemplary Industrial Unit',st5e:'BEYOND TRAILERS',st5t:'The region’s largest<br>LPG tanker maker.',st5d:'A new production line for liquefied-gas tankers has made Maral the largest producer in the region and Asia, while city-bus refurbishment and minibus production add to national manufacturing.',st5v:'Watch the LPG tanker',st5s:'City-bus refurbishment · Minibus production',st6e:'EXPORTS',st6t:'From Urmia<br>to three continents.',st6d:'Maral exports to European, Asian and Middle Eastern countries, including a four-axle curtainsider built for the Russian market.',st7e:'THE PROMISE',st7t:'100,000 km<br>of peace of mind.',st7d:'A 100,000 km or 12-month warranty, 40+ authorised service centres and one clear goal: to lead trailer and trailer-parts manufacturing in the Middle East.',st7c:'Choose my next trailer <span>↗</span>',st7g:'or 12-month warranty',storyNote:'Based on Maral’s “About us” page, updated to 37 years. Maral’s sources cite both 20+ and 40+ service centres; to be confirmed.',g2Name:'Mehvarsazan Chichest'});
const storyEl=$('#story'),chapters=$$('.chapter',storyEl),storyDots=$$('.story-dots li',storyEl);
let storyIndex=-1,storyScheduled=false;
$('#people-dots').append(...Array.from({length:120},()=>document.createElement('i')));
function storyCounts(ch,p){$$('[data-count-to]',ch).forEach(el=>{const v=Number(el.dataset.countTo)*Math.min(1,p*1.6);el.textContent=nf(Math.round(v))+(el.dataset.suffix||'');});}
function updateStory(){
 storyScheduled=false;if(!storyEl.classList.contains('story-live'))return;
 const r=storyEl.getBoundingClientRect();document.body.classList.toggle('in-story',r.top<=0&&r.bottom>=innerHeight);if(r.bottom<0||r.top>innerHeight)return;
 const prog=Math.min(Math.max(-r.top/(r.height-innerHeight),0),.9999),pos=prog*chapters.length,i=Math.floor(pos),p=pos-i;
 if(i!==storyIndex){storyIndex=i;chapters.forEach((c,n)=>{c.classList.toggle('active',n===i);c.classList.toggle('past',n<i);c.inert=n!==i;});storyDots.forEach((d,n)=>d.classList.toggle('on',n<=i));$('#story-count').textContent=`${fmt(i+1)} / ${fmt(chapters.length)}`;$('#story-year').textContent=chapters[i].dataset.year;}
 const ch=chapters[i];ch.style.setProperty('--p',p.toFixed(3));storyCounts(ch,p);
 if(i===1){const lit=Math.round(Math.min(1,p*1.6)*120);$$('#people-dots i').forEach((d,n)=>d.classList.toggle('on',n<lit));}
 $('#story-bar').style.width=(prog*100)+'%';
}
function renderStory(){if(storyEl.classList.contains('story-live')){storyIndex=-1;updateStory();}else{chapters.forEach(c=>storyCounts(c,1));$$('#people-dots i').forEach(d=>d.classList.add('on'));}}
/* Pinned scroll stories need height: phones in landscape (and other short screens) get the static layout */
const pinnable=()=>!prefersReduced&&innerHeight>=520;
if(pinnable()&&has('#story'))storyEl.classList.add('story-live');
window.addEventListener('scroll',()=>{if(!storyScheduled){storyScheduled=true;requestAnimationFrame(updateStory);}},{passive:true});
window.addEventListener('resize',()=>{storyIndex=-1;updateStory();});
$$('[data-play]').forEach(b=>b.addEventListener('click',()=>openTV(b.dataset.play)));
const STORE='maral-journey-v1';
const state=(()=>{try{return JSON.parse(localStorage.getItem(STORE))||{};}catch{return {};}})();
function saveState(){try{localStorage.setItem(STORE,JSON.stringify(state));}catch{}}
const locale=()=>({fa:'fa-IR',en:'en-US',ru:'ru-RU',ar:'ar-AE'})[lang];
const nf=(n,d=0)=>Number(n).toLocaleString(locale(),{maximumFractionDigits:d});
const fillIn=(s,o)=>s.replace(/\{(\w+)\}/g,(_,k)=>o[k]);
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3500);}
let orderStep=0;
function renderFacts(animate=false){
 $$('.count').forEach(el=>{const to=Number(el.dataset[lang==='fa'?'fa':'en']||el.dataset.to),plain='plain' in el.dataset,suffix=el.dataset.suffix||'';
  const show=v=>{el.textContent=(plain?Math.round(v).toLocaleString(locale(),{useGrouping:false}):nf(Math.round(v)))+suffix;};
  if(!animate||prefersReduced){show(to);return;}
  const from=plain?to-30:0,start=performance.now();const step=now=>{const p=Math.min((now-start)/1400,1);show(from+(to-from)*(1-Math.pow(1-p,3)));if(p<1)requestAnimationFrame(step);};requestAnimationFrame(step);});
}
const factsObserver=new IntersectionObserver(es=>{if(es.some(e=>e.isIntersecting)){factsObserver.disconnect();renderFacts(true);}},{threshold:.35});factsObserver.observe($('#facts'));
const planDefaults={tipper:{amount:12000,unit:'unitT',label:'plAmountTipper',fill:90},fuel:{amount:1500000,unit:'unitL',label:'plAmountFuel',fill:95},reefer:{amount:4000,unit:'unitM3',label:'plAmountReefer',fill:85},flatbed:{amount:6000,unit:'unitT',label:'plAmountFlatbed',fill:90}};
function setPlanModel(id){if(!has('#planner'))return;$('#pl-model').value=id;$('#pl-amount').value=planDefaults[id].amount;$('#pl-fill').value=planDefaults[id].fill;renderPlanner();}
function planCalc(){
 const id=$('#pl-model').value,num=s=>Math.max(0,Number($(s).value)||0);
 const f=num('#pl-fill')/100,amount=num('#pl-amount'),days=num('#pl-days'),trips=num('#pl-trips'),payload=num('#pl-payload');
 let perTrip,flag;
 if(id==='tipper'){const byVolume=32*Number($('#pl-material').value)*f;perTrip=Math.min(byVolume,payload);flag=byVolume>payload?fillIn(t('plWeightLimited'),{v:nf(byVolume,1)}):t('plVolumeLimited');}
 else if(id==='fuel'){perTrip=33400*f;flag=t('plFuelFlag');}
 else if(id==='reefer'){perTrip=82*f;flag=t('plReeferFlag');}
 else{perTrip=payload;flag=t('plFlatbedFlag');}
 const tripsMonth=perTrip>0?Math.ceil(amount/perTrip):0,perTrailer=days*trips,fleet=tripsMonth&&perTrailer?Math.ceil(tripsMonth/perTrailer):0;
 return {model:id,amount,unit:planDefaults[id].unit,perTrip,tripsMonth,fleet,util:fleet?tripsMonth/(fleet*perTrailer):0,flag};
}
function planSummary(r){return `${seriesLabel(r.model)} — `+fillIn(t('plSummary'),{a:nf(r.amount),u:t(r.unit),tr:nf(r.tripsMonth),f:nf(r.fleet)});}
function renderPlanner(){
 if(!has('#planner'))return null;
 const id=$('#pl-model').value;
 $$('[data-show]').forEach(el=>{el.hidden=!el.dataset.show.split(' ').includes(id);});
 $('#pl-amount-label').textContent=t(planDefaults[id].label);$('#pl-fill-out').textContent=nf($('#pl-fill').value)+'%';
 const r=planCalc();
 $('#pl-fleet').textContent=nf(r.fleet);$('#pl-per-trip').textContent=`${nf(r.perTrip,1)} ${t(r.unit)}`;$('#pl-trips-month').textContent=nf(r.tripsMonth);$('#pl-util').textContent=nf(r.util*100)+'%';$('#pl-limit').textContent=r.flag;
 $('#pl-use').disabled=!r.fleet;
 return r;
}
function serviceMessage(){
 const val=s=>$(s).value.trim()||t('svEmpty'),opt=s=>$(s).selectedOptions[0].textContent;
 return [t('svMsgTitle'),'',`${t('svModel')}: ${opt('#sv-model')}`,`${t('svChassis')}: ${val('#sv-chassis')}`,`${t('svYear')}: ${val('#sv-year')}`,`${t('svNeed')}: ${opt('#sv-need')}`,`${t('svCity')}: ${val('#sv-city')}`,`${t('svDesc')}: ${val('#sv-desc')}`].join('\n');
}
function renderService(){if(!has('#planner'))return;$('#sv-message').textContent=serviceMessage();}
function setTool(id){$$('[data-tool]').forEach(b=>{const active=b.dataset.tool===id;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;});$('#tool-fleet').hidden=id!=='fleet';$('#tool-service').hidden=id!=='service';}
function goTool(id){if(!has('#planner')){location.href='tools.html?tool='+id;return;}setTool(id);$('#planner').scrollIntoView({behavior:prefersReduced?'instant':'smooth',block:'start'});}
function renderJourney(){
 const done={explore:!!state.explored,plan:!!state.plan,request:!!state.ref};
 $$('.journey-steps li').forEach(li=>li.classList.toggle('done',done[li.dataset.step]));
 const parts=[t('option'+model[0].toUpperCase()+model.slice(1))];if(state.plan)parts.push(fillIn(t('jFleet'),{n:nf(state.plan.fleet)}));if(state.ref)parts.push(state.ref);
 $('#journey-summary').textContent=parts.join(' · ');$('#journey-cta').innerHTML=t(state.ref?'jView':'jCta');
}
const orderFields=['form-model','form-quantity','form-timing','form-buyer','form-cargo','form-notes','form-name','form-phone','form-email','form-company','form-city','form-pref'];
function storeForm(){state.form=Object.fromEntries(orderFields.map(id=>[id,$('#'+id).value]));state.form.plan=$('#form-plan').checked;saveState();}
function restoreForm(){const f=state.form;if(!f)return;orderFields.forEach(id=>{if(f[id]!=null)$('#'+id).value=f[id];});$('#form-plan').checked=f.plan!==false;}
function renderPlanAttach(){$('#plan-attach').hidden=!state.plan;if(state.plan)$('#plan-attach-text').textContent=planSummary(state.plan);}
function renderReview(){const box=$('#order-review');box.replaceChildren();reviewRows(draft()).forEach(([k,v])=>{const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=k;dd.textContent=v;box.append(dt,dd);});}
function setOrderStep(i){
 orderStep=i;const sets=$$('.order-step');sets.forEach((fs,n)=>{fs.hidden=n!==i;});
 $$('.order-steps li').forEach((li,n)=>{li.classList.toggle('active',n===i);li.classList.toggle('done',n<i);if(n===i)li.setAttribute('aria-current','step');else li.removeAttribute('aria-current');});
 $('#order-back').hidden=i===0;$('#order-next').hidden=i===sets.length-1;$('#order-submit').hidden=i!==sets.length-1;
 if(i===1)renderPlanAttach();if(i===sets.length-1)renderReview();
}
function stepValid(){return $$('input,select,textarea',$$('.order-step')[orderStep]).every(el=>el.reportValidity());}
function showDone(){$('#inquiry-form').hidden=true;$('.order-steps').hidden=true;$('#inquiry-dialog .dialog-intro').hidden=true;$('#order-done').hidden=false;$('#done-ref').textContent=state.ref;}
function hideDone(){$('#inquiry-form').hidden=false;$('.order-steps').hidden=false;$('#inquiry-dialog .dialog-intro').hidden=false;$('#order-done').hidden=true;}
function renderTools(){
 renderPlanner();renderService();renderJourney();renderFacts();renderPlanAttach();if(orderStep===3)renderReview();renderMedia();renderStory();renderGallery();renderBuild();renderCatalog();renderTrailer();renderTray();showDraft(draftIndex);renderFilms();renderDownloads();renderKb();renderReader();renderModelFaq();renderFaq();renderContact();if($('#lightbox').open)renderLightbox();
 $('#sv-chassis').placeholder=t('chassisPh');$('#sv-year').placeholder=t('yearPh');$('#sv-city').placeholder=t('cityPh');
 $('#form-phone').placeholder='+98 …';$('#journey').setAttribute('aria-label',t('jLabel'));
}
$('#pl-model').addEventListener('change',()=>setPlanModel($('#pl-model').value));
$('#fleet-form').addEventListener('input',renderPlanner);$('#fleet-form').addEventListener('submit',e=>e.preventDefault());
$('#pl-use').addEventListener('click',()=>{const r=renderPlanner();if(!r.fleet)return;state.plan=r;state.explored=true;$('#form-model').value=r.model;$('#form-quantity').value=String(r.fleet);$('#form-plan').checked=true;if(!$('#form-cargo').value.trim())$('#form-cargo').value=t('cargo'+r.model[0].toUpperCase()+r.model.slice(1));storeForm();renderJourney();openInquiry(true);toast(t('plUsed'));});
$('#service-form').addEventListener('input',renderService);$('#service-form').addEventListener('submit',e=>e.preventDefault());
$('#sv-copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(serviceMessage());toast(t('svCopied'));}catch{const range=document.createRange();range.selectNodeContents($('#sv-message'));const sel=getSelection();sel.removeAllRanges();sel.addRange(range);toast(t('svSelect'));}});
$$('[data-tool]').forEach(b=>b.addEventListener('click',()=>setTool(b.dataset.tool)));
$('.tool-tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const next=$('[data-tool][aria-selected=false]');setTool(next.dataset.tool);next.focus();});
$$('.group-card').forEach(b=>b.addEventListener('click',()=>{const r=b.dataset.route;if(r==='mission')location.href='products.html';else if(r==='contact')openDialog('service-dialog');else location.href='tools.html?tool=service&need='+b.dataset.need;}));
$('#order-next').addEventListener('click',()=>{if(stepValid()){storeForm();setOrderStep(orderStep+1);}});
$('#order-back').addEventListener('click',()=>setOrderStep(Math.max(0,orderStep-1)));
$('#inquiry-form').addEventListener('submit',e=>{e.preventDefault();if(!stepValid())return;if(orderStep<3){setOrderStep(orderStep+1);return;}
 const d=new Date();state.ref='MRL-'+d.toISOString().slice(2,10).replace(/-/g,'')+'-'+Math.random().toString(36).slice(2,6).toUpperCase();storeForm();showDone();renderJourney();});
$('#new-request').addEventListener('click',()=>{delete state.ref;saveState();hideDone();setOrderStep(0);renderJourney();});
$('#journey-cta').addEventListener('click',()=>openInquiry());
let journeyScheduled=false;const updateJourney=()=>{const on=scrollY>innerHeight*.75;$('#journey').hidden=!on;document.body.classList.toggle('has-journey',on);journeyScheduled=false;};
window.addEventListener('scroll',()=>{if(!journeyScheduled){journeyScheduled=true;requestAnimationFrame(updateJourney);}},{passive:true});
if(state.model&&models[state.model])model=state.model;
restoreForm();
