/* Gallery: images hotlinked from maralsanat.com/en/gallery, filterable grid, marquee and lightbox */
const GALLERY_BASE='https://www.maralsanat.com/uploads/gallery/';
const galleryItems=[['968-1761637663','tipper'],['239-1761634349','lpg'],['376-1761634677','curtain'],['563-1761634610','tipper'],['121-1761634586','fuel'],['971-1761634478','plant'],['851-1761634498','tipper'],['729-1761634297','cement'],['848-1761634519','curtain'],['204-1762343579','container'],['131-1761634325','tipper'],['474-1761634632','tanker'],['442-1761637918','expo'],['551-1761637693','tipper'],['523-1761634733','lpg'],['930-1761634542','curtain'],['397-1761637723','fuel'],['792-1761634449','tipper'],['134-1761634659','tanker'],['736-1761634565','curtain'],['62-1761634212','tipper'],['783-1761637883','plant']].map(([file,type])=>({src:GALLERY_BASE+file+'.webp',type}));
const galleryGroups={all:null,tipper:['tipper'],tanker:['fuel','tanker','lpg','cement'],curtain:['curtain'],container:['container'],plant:['plant','expo']};
const galleryGroupOf=type=>Object.keys(galleryGroups).find(g=>g!=='all'&&galleryGroups[g].includes(type));
let galleryFilter='all',lightboxIndex=0;
const galleryVisible=()=>galleryItems.filter(g=>!galleryGroups[galleryFilter]||galleryGroups[galleryFilter].includes(g.type));
function galleryImage(g,cls=''){const img=document.createElement('img');img.src=g.src;img.alt=t('galType_'+g.type);img.loading='lazy';img.decoding='async';if(cls)img.className=cls;img.addEventListener('error',()=>img.closest('li')?.setAttribute('hidden',''));return img;}
function renderGallery(){
 if(!has('#gallery'))return;
 const bar=$('#gallery-filters');bar.replaceChildren();
 Object.keys(galleryGroups).forEach(g=>{const b=document.createElement('button');b.type='button';b.className='gallery-filter';b.setAttribute('aria-pressed',String(g===galleryFilter));const n=galleryItems.filter(i=>!galleryGroups[g]||galleryGroups[g].includes(i.type)).length;b.innerHTML=`<span>${t(g==='all'?'galAll':'galF_'+g)}</span><sup>${nf(n)}</sup>`;b.addEventListener('click',()=>setGalleryFilter(g));bar.append(b);});
 const grid=$('#gallery-grid');grid.replaceChildren();
 galleryVisible().forEach((g,i)=>{const li=document.createElement('li');li.className='gallery-item'+(i%7===0?' feature':'');li.style.setProperty('--i',i);li.style.viewTransitionName='gal-'+galleryItems.indexOf(g);const b=document.createElement('button');b.type='button';b.className='gallery-tile';b.setAttribute('aria-label',`${t('galOpen')}: ${t('galType_'+g.type)}`);const cap=document.createElement('span');cap.className='gallery-cap';cap.innerHTML=`<b>${fmt(i+1)}</b><span></span>`;cap.lastChild.textContent=t('galType_'+g.type);b.append(galleryImage(g),cap);b.addEventListener('click',()=>{lightboxMode='images';openLightbox(i);});li.append(b);grid.append(li);});
 $('#gallery-count').textContent=fillIn(t('galCount'),{n:nf(galleryVisible().length)});
 ['#marquee-a','#marquee-b'].forEach((sel,row)=>{const el=$(sel);if(el.childElementCount)return;const half=galleryItems.filter((_,i)=>i%2===row);[...half,...half].forEach(g=>el.append(galleryImage(g)));});
}
function setGalleryFilter(g){const run=()=>{galleryFilter=g;renderGallery();};if(document.startViewTransition&&!prefersReduced)document.startViewTransition(run);else run();}
function lightboxList(){
 if(lightboxMode==='films')return FILMS.map(filmItem);
 if(page==='trailer'&&trModel){const f=FILMS.find(x=>x.file===trModel.video);return [...(f?[filmItem(f)]:[]),...trModel.gallery.map(src=>({src,title:trModel.name[lang],sub:t('fam_'+trModel.fam)}))];}
 return galleryVisible().map(g=>({src:g.src,type:g.type,title:t('galType_'+g.type),sub:t('galF_'+galleryGroupOf(g.type))}));
}
function renderLightbox(){
 const list=lightboxList();if(!list.length)return;lightboxIndex=(lightboxIndex+list.length)%list.length;const g=list[lightboxIndex];
 const vid=$('#lb-video');vid.pause?.();$('#lb-img').hidden=!!g.video;vid.hidden=!g.video;if(g.video){if(vid.getAttribute('src')!==g.video){vid.setAttribute('src',g.video);vid.setAttribute('poster',g.src);}vid.play?.().catch(()=>{});}else $('#lb-img').src=g.src;$('#lb-img').alt=g.title;$('#lb-title').textContent=g.title;$('#lb-type').textContent=g.sub;$('#lb-count').textContent=`${fmt(lightboxIndex+1)} / ${fmt(list.length)}`;$('#lb-source').href=g.src;
 const thumbs=$('#lb-thumbs');thumbs.replaceChildren();list.forEach((item,i)=>{const li=document.createElement('li'),b=document.createElement('button');b.type='button';b.setAttribute('aria-current',String(i===lightboxIndex));const im=document.createElement('img');im.src=item.src;im.alt='';im.loading='lazy';b.append(im);b.addEventListener('click',()=>{lightboxIndex=i;renderLightbox();});li.append(b);thumbs.append(li);});
 thumbs.children[lightboxIndex]?.scrollIntoView({block:'nearest',inline:'center'});
}
function openLightbox(i){lightboxIndex=i;renderLightbox();openDialog('lightbox');}
function stepLightbox(d){lightboxIndex+=d;renderLightbox();}
let trModel=null,lightboxMode='images';
/* Films from maralsanat.com/en/media, streamed from Maral's server (MP4, range requests) */
const MEDIA_BASE='https://www.maralsanat.com/uploads/media/';
const FILMS=[{file:'721-1763360171',poster:'158-1763360171',key:'vidTent',model:'curtain-std'},{file:'685-1763278255',poster:'636-1763278255',key:'vidCurtain',model:'curtain-roof'},{file:'31-1763278208',poster:'140-1763278208',key:'vidLpg',model:'lpg'}];
const filmItem=f=>({src:MEDIA_BASE+f.poster+'.jpg',video:MEDIA_BASE+'video/'+f.file+'.mp4',title:t(f.key),sub:t('filmMeta'),model:f.model});
function renderFilms(){
 if(!has('#films-grid'))return;
 $('#films-grid').replaceChildren(...FILMS.map((f,i)=>{const it=filmItem(f),li=document.createElement('li'),b=document.createElement('button');b.type='button';b.className='film-tile';b.innerHTML=`<img alt="" loading="lazy" src="${it.src}"><span class="film-play" aria-hidden="true">▶</span><span class="film-cap"><b></b><small></small></span>`;$('b',b).textContent=it.title;$('small',b).textContent=it.sub;b.setAttribute('aria-label',it.title);b.addEventListener('click',()=>{lightboxMode='films';openLightbox(i);});li.append(b);return li;}));
}
$('#lightbox').addEventListener('close',()=>{$('#lb-video').pause?.();});
$('#lb-prev').addEventListener('click',()=>stepLightbox(-1));$('#lb-next').addEventListener('click',()=>stepLightbox(1));
$('#lightbox').addEventListener('keydown',e=>{if(e.key==='ArrowRight')stepLightbox(rtl()?-1:1);if(e.key==='ArrowLeft')stepLightbox(rtl()?1:-1);});
{let x0=null;$('#lightbox').addEventListener('pointerdown',e=>{x0=e.clientX;});$('#lightbox').addEventListener('pointerup',e=>{if(x0===null)return;const dx=e.clientX-x0;x0=null;if(Math.abs(dx)>60)stepLightbox((dx<0)!==rtl()?1:-1);});}
$('#lb-request').addEventListener('click',()=>{$('#lightbox').close();if(page==='trailer'&&trModel){requestModel(trModel);return;}if(lightboxMode==='films'){const fm=CAT.find(m=>m.id===FILMS[lightboxIndex]?.model);if(fm){requestModel(fm);return;}openInquiry();return;}const g=galleryVisible()[lightboxIndex],m={tipper:'tipper',fuel:'fuel',tanker:'fuel'}[g.type];if(m)$('#form-model').value=m;openInquiry(!!m);});
/* Home: scroll-driven build sequence, from steel plate to a delivered trailer.
   Each named range maps scroll position (in steps) to a 0–1 CSS variable that the SVG parts read. */
const buildEl=$('#build'),buildSteps=$$('.build-step'),buildRail=$$('.build-rail li');
const buildRanges={plates:[.9,1.7],cut:[2,2.85],laser:[1.9,2.1],laserX:[2,2.85],laserOut:[2.85,3],platesOut:[3,3.4],bpOut:[2.9,3.6],chassis:[2.9,3.7],weld:[3.1,3.3],weldOut:[3.8,4],tank:[4,4.45],paint:[4.25,4.7],tankOut:[4.55,4.95],axles:[5,5.75],body:[6,6.75],hyd:[7,7.4],light:[7.2,7.5],tilt:[7.35,7.95],qc:[8,8.85],qcOut:[8.9,9.1],deliver:[9.05,9.85]};
let buildIndex=-1,buildScheduled=false;
function setBuild(pos){
 const clamp=([a,b])=>Math.min(1,Math.max(0,(pos-a)/(b-a)));
 for(const [k,r] of Object.entries(buildRanges))buildEl.style.setProperty('--'+k,clamp(r).toFixed(3));
 buildEl.style.setProperty('--tiltdeg',(Math.sin(clamp(buildRanges.tilt)*Math.PI)*20).toFixed(2)+'deg');
 const i=Math.min(buildSteps.length-1,Math.floor(pos));
 if(i!==buildIndex){buildIndex=i;buildSteps.forEach((st,n)=>{st.classList.toggle('active',n===i);st.classList.toggle('past',n<i);if(buildEl.classList.contains('build-live'))st.inert=n!==i;});buildRail.forEach((r,n)=>{r.classList.toggle('on',n<=i);r.classList.toggle('now',n===i);});$('#build-count').textContent=`${fmt(i)} / ${fmt(buildSteps.length-1)}`;}
}
function updateBuild(){
 buildScheduled=false;if(!buildEl.classList.contains('build-live'))return;
 const r=buildEl.getBoundingClientRect();if(r.bottom<0||r.top>innerHeight)return;
 const prog=Math.min(Math.max(-r.top/(r.height-innerHeight),0),1);setBuild(Math.min(prog*buildSteps.length,buildSteps.length-.001));$('#build-bar').style.width=(prog*100)+'%';
}
function renderBuild(){if(!has('#build'))return;buildIndex=-1;if(buildEl.classList.contains('build-live'))updateBuild();else setBuild(buildSteps.length-.001);}
if(has('#build')&&pinnable())buildEl.classList.add('build-live');
function applyMotionModes(){
 const live=pinnable();
 if(has('#build')&&live!==buildEl.classList.contains('build-live')){buildEl.classList.toggle('build-live',live);buildSteps.forEach(st=>{st.inert=false;});renderBuild();}
 if(has('#story')&&live!==storyEl.classList.contains('story-live')){storyEl.classList.toggle('story-live',live);chapters.forEach(c=>{c.inert=false;c.classList.remove('active','past');c.style.removeProperty('--p');});document.body.classList.remove('in-story');renderStory();}
}
let modeScheduled=false;
window.addEventListener('resize',()=>{if(!modeScheduled){modeScheduled=true;requestAnimationFrame(()=>{modeScheduled=false;applyMotionModes();});}});
window.addEventListener('scroll',()=>{if(!buildScheduled){buildScheduled=true;requestAnimationFrame(updateBuild);}},{passive:true});
window.addEventListener('resize',()=>{buildIndex=-1;updateBuild();});
