/* Product catalogue: blueprint cards with an x-ray photo lens, family filters, search,
   side-by-side compare and one data-driven page per model (trailer.html?m=id). */
const CAT=typeof maralCatalog!=='undefined'?maralCatalog:[];
const FAMS=['tipper','sidewall','bulker','tanker','curtain','container','flatbed','lowbed','reefer'];
const SPEC_ORDER=['chassis','tank','body','floor','curtain','cylinder','discharge','axles','suspension','braking','painting','electric','legs','kingpin','tyres','rim','dims','ramp','door'];
const FIG_WORDS={'5-stage':{fa:'۵ مرحله‌ای',ru:'5 ступеней',ar:'5 مراحل'},'EU-made':{fa:'ساخت اروپا',ru:'Европа',ar:'صنع أوروبي'},'PU sandwich':{fa:'ساندویچ PU',ru:'PU-сэндвич',ar:'ألواح PU'}};
let catFam=FAMS.includes(params.get('fam'))?params.get('fam'):'all',catQuery='',catMode='drawing',draftIndex=0,draftTimer=0;
state.compare=Array.isArray(state.compare)?state.compare.filter(id=>CAT.some(m=>m.id===id)):[];
function pickedModel(){return CAT.find(m=>m.id===state.pick)||null;}
function figValue(v){if(lang==='en')return v;return (FIG_WORDS[v]?.[lang]||v).replace(/(\d)\s*t\b/g,'$1 '+t('unitT')).replace(/\bft\b/,t('unitFt'));}
function specRows(m){return lang==='fa'?(m.specs.fa.length?m.specs.fa:m.specs.en):m.specs.en;}
const specLabel=row=>row[0].startsWith('other')?row[1]:t('sp_'+row[0].replace(/\d+$/,''));
function catCard(m){
 const li=document.createElement('li'),href='trailer.html?m='+m.id;li.className='cat-card';li.style.viewTransitionName='cat-'+m.id;
 li.innerHTML=`<a class="cat-visual" href="${href}"><img class="cat-drawing" alt="" loading="lazy" decoding="async" src="${m.drawing}"><img class="cat-photo" alt="" loading="lazy" decoding="async" src="${m.photo}"><span class="cat-lens" aria-hidden="true"></span><span class="cat-code">${m.code}</span><span class="cat-fam"></span></a><div class="cat-info"><h3><a href="${href}"></a></h3><dl class="cat-figs"></dl><div class="cat-actions"><label class="cmp-toggle"><input type="checkbox" data-cmp="${m.id}"><span></span></label><a class="cat-more" href="${href}"><span></span> <i aria-hidden="true">↗</i></a></div></div>`;
 $('.cat-fam',li).textContent=t('fam_'+m.fam);$('h3 a',li).textContent=m.name[lang];$('.cat-visual',li).setAttribute('aria-label',m.name[lang]);
 $('.cmp-toggle span',li).textContent=t('catCompare');$('.cat-more span',li).textContent=t('catDetails');$('[data-cmp]',li).checked=state.compare.includes(m.id);
 const dl=$('.cat-figs',li);m.figs.slice(0,3).forEach(([k,v])=>{const d=document.createElement('div');d.innerHTML='<dt></dt><dd></dd>';d.firstChild.textContent=t('fig_'+k);d.lastChild.textContent=figValue(v);dl.append(d);});
 const vis=$('.cat-visual',li);
 vis.addEventListener('pointermove',e=>{const r=vis.getBoundingClientRect();vis.style.setProperty('--mx',(e.clientX-r.left)+'px');vis.style.setProperty('--my',(e.clientY-r.top)+'px');});
 vis.addEventListener('pointerenter',e=>{if(e.pointerType!=='touch')vis.classList.add('lens');});vis.addEventListener('pointerleave',()=>vis.classList.remove('lens'));
 return li;
}
const catMatches=m=>(catFam==='all'||m.fam===catFam)&&(!catQuery.trim()||[m.code,m.id,...Object.values(m.name),t('fam_'+m.fam)].join(' ').toLowerCase().includes(catQuery.trim().toLowerCase()));
function renderCatalog(){
 if(!has('#catalog'))return;
 const bar=$('#cat-fams');bar.replaceChildren();
 ['all',...FAMS].forEach(f=>{const b=document.createElement('button');b.type='button';b.className='cat-fam-btn';b.setAttribute('aria-pressed',String(f===catFam));b.innerHTML=`<span></span><sup>${nf(f==='all'?CAT.length:CAT.filter(m=>m.fam===f).length)}</sup>`;b.firstChild.textContent=t(f==='all'?'galAll':'fam_'+f);b.addEventListener('click',()=>setCatFam(f));bar.append(b);});
 const list=CAT.filter(catMatches),grid=$('#cat-grid');grid.replaceChildren(...list.map(catCard));grid.dataset.mode=catMode;$('#cat-empty').hidden=list.length>0;
 $$('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===catMode)));
 $('#cat-search').placeholder=t('catSearch');$('#cat-search').setAttribute('aria-label',t('catSearch'));
 $('#cat-n-models').textContent=nf(CAT.length);$('#cat-n-fams').textContent=nf(FAMS.length);$('#cat-n-drawings').textContent=nf(CAT.filter(m=>m.drawing).length);
}
function setCatFam(f){const run=()=>{catFam=f;renderCatalog();};if(document.startViewTransition&&!prefersReduced)document.startViewTransition(run);else run();const u=new URL(location.href);if(f==='all')u.searchParams.delete('fam');else u.searchParams.set('fam',f);history.replaceState(null,'',u);}
$('#cat-search').addEventListener('input',e=>{catQuery=e.target.value;renderCatalog();});
$$('[data-mode]').forEach(b=>b.addEventListener('click',()=>{catMode=b.dataset.mode;renderCatalog();}));
function showDraft(i){
 if(!has('#drafting')||!CAT.length)return;draftIndex=(i+CAT.length)%CAT.length;const m=CAT[draftIndex],d=$('#drafting');
 d.classList.remove('drawing');void d.offsetWidth;$('#draft-img').src=m.drawing;$('#draft-code').textContent=m.code;$('#draft-name').textContent=m.name[lang];$('#draft-count').textContent=`${fmt(draftIndex+1)} / ${fmt(CAT.length)}`;d.href='trailer.html?m='+m.id;d.setAttribute('aria-label',m.name[lang]);d.classList.add('drawing');
}
function startDrafting(){clearInterval(draftTimer);if(!has('#drafting')||prefersReduced)return;draftTimer=setInterval(()=>{if(!document.hidden)showDraft(draftIndex+1);},4200);}
$('#drafting').addEventListener('mouseenter',()=>clearInterval(draftTimer));$('#drafting').addEventListener('mouseleave',startDrafting);
/* Compare: up to three models, kept in the visitor's browser */
function toggleCompare(id,on){const c=state.compare,i=c.indexOf(id);if(on&&i<0){if(c.length>=3){toast(t('cmpMax'));return false;}c.push(id);}if(!on&&i>=0)c.splice(i,1);saveState();renderTray();return true;}
function syncCmpBoxes(){$$('[data-cmp]').forEach(cb=>{cb.checked=state.compare.includes(cb.dataset.cmp);});if(trModel)$('#tr-cmp').checked=state.compare.includes(trModel.id);}
document.addEventListener('change',e=>{const cb=e.target.closest('[data-cmp]');if(!cb)return;if(!toggleCompare(cb.dataset.cmp,cb.checked))cb.checked=false;syncCmpBoxes();});
$('#tr-cmp').addEventListener('change',e=>{if(!trModel)return;if(!toggleCompare(trModel.id,e.target.checked))e.target.checked=false;syncCmpBoxes();});
function renderTray(){
 if(!has('#compare-tray'))return;const c=state.compare;$('#compare-tray').hidden=!c.length;document.body.classList.toggle('has-compare',c.length>0);
 $('#tray-label').textContent=fillIn(t('cmpTray'),{n:nf(c.length)});$('#tray-open').disabled=c.length<2;
 const ol=$('#tray-items');ol.replaceChildren(...c.map(id=>{const m=CAT.find(x=>x.id===id),li=document.createElement('li');li.innerHTML=`<img alt="" src="${m.drawing}"><b>${m.code}</b><button type="button" data-rm="${m.id}">×</button>`;$('button',li).setAttribute('aria-label',`${t('cmpRemove')}: ${m.name[lang]}`);return li;}));
}
$('#tray-items').addEventListener('click',e=>{const b=e.target.closest('[data-rm]');if(!b)return;toggleCompare(b.dataset.rm,false);syncCmpBoxes();if($('#cat-compare').open)renderCompareTable();});
$('#tray-clear').addEventListener('click',()=>{state.compare=[];saveState();renderTray();syncCmpBoxes();});
$('#tray-open').addEventListener('click',()=>{renderCompareTable();openDialog('cat-compare');});
function renderCompareTable(){
 const ms=state.compare.map(id=>CAT.find(m=>m.id===id)),table=$('#cmp-table');table.replaceChildren();if(!ms.length){$('#cat-compare').close();return;}
 const head=document.createElement('thead'),hr=document.createElement('tr');hr.append(document.createElement('th'));
 ms.forEach(m=>{const th=document.createElement('th');th.innerHTML=`<img alt="" src="${m.drawing}"><span class="cmp-code">${m.code}</span><a href="trailer.html?m=${m.id}"></a>`;$('a',th).textContent=m.name[lang];hr.append(th);});head.append(hr);table.append(head);
 const body=document.createElement('tbody'),row=(label,cells,cls='')=>{const tr=document.createElement('tr');if(cls)tr.className=cls;const th=document.createElement('th');th.scope='row';th.textContent=label;tr.append(th);cells.forEach(c=>{const td=document.createElement('td');td.textContent=c||'—';tr.append(td);});body.append(tr);};
 const figKeys=[...new Set(ms.flatMap(m=>m.figs.map(f=>f[0])))];
 figKeys.forEach(k=>row(t('fig_'+k),ms.map(m=>{const f=m.figs.find(x=>x[0]===k);return f?figValue(f[1]):'';}),'cmp-fig'));
 row(t('trSpecsEyebrow'),ms.map(()=>''),'cmp-sep');
 SPEC_ORDER.forEach(k=>{const vals=ms.map(m=>specRows(m).filter(r=>r[0].replace(/\d+$/,'')===k).map(r=>r[2]).join(' / '));if(vals.some(Boolean))row(t('sp_'+k),vals);});
 table.append(body);
}
/* One page per model */
function requestModel(m){const fm={tipper:'tipper',reefer:'reefer',flatbed:'flatbed'}[m.fam]||(m.id==='fuel'?'fuel':null);if(fm)$('#form-model').value=fm;if(!$('#form-cargo').value.trim())$('#form-cargo').value=t('fam_'+m.fam);openInquiry(true,m.id);}
function renderTrailer(){
 if(page!=='trailer'||!CAT.length)return;
 const m=trModel=CAT.find(x=>x.id===params.get('m'))||CAT[0];
 document.title=`${m.name[lang]} — MARAL`;$('#tr-fam').textContent=t('fam_'+m.fam);$('#tr-fam').href=`products.html?fam=${m.fam}#catalog`;
 $('#tr-code').textContent=m.code;$('#tr-name').textContent=m.name[lang];$('#tr-desc').textContent=t('famDesc_'+m.fam);
 $('#tr-drawing').src=m.drawing;$('#tr-photo').src=m.photo;$('#tr-photo').alt=m.name[lang];$('#tr-split').setAttribute('aria-label',t('trDrag'));
 $('#tr-pdf').hidden=!m.pdf;if(m.pdf)$('#tr-pdf').href=m.pdf;$('#tr-source').href=m.source;
 const figs=$('#tr-figs');figs.replaceChildren(...m.figs.map(([k,v])=>{const d=document.createElement('div');d.innerHTML='<dt></dt><dd></dd>';d.firstChild.textContent=t('fig_'+k);d.lastChild.textContent=figValue(v);return d;}));
 const rows=specRows(m);$('#tr-spec-note').textContent=!rows.length?t('trSpecMissing'):['ru','ar'].includes(lang)?t('trSpecNoteEn'):t('trSpecNote');
 $('#tr-spec-sheet').replaceChildren(...rows.map((r,i)=>{const li=document.createElement('li');li.innerHTML='<span class="spec-no"></span><b></b><p></p>';li.children[0].textContent=fmt(i+1);li.children[1].textContent=specLabel(r);li.children[2].textContent=r[2];return li;}));
 const acc=lang==='fa'?(m.acc.fa.length?m.acc.fa:m.acc.en):(m.acc.en.length?m.acc.en:[]);$('.tr-acc').hidden=!acc.length;
 $('#tr-acc').replaceChildren(...acc.map(a=>{const li=document.createElement('li');li.textContent=a;return li;}));
 renderDatasheet(m);
 const film=FILMS.find(x=>x.file===m.video),offset=film?1:0;
 $('#tr-gallery').hidden=!m.gallery.length&&!film;$('#tr-gal-count').textContent=fillIn(t('galCount'),{n:nf(m.gallery.length)});
 $('#tr-strip').replaceChildren(...(film?[(()=>{const it=filmItem(film),li=document.createElement('li'),b=document.createElement('button');b.type='button';b.className='strip-film';b.innerHTML=`<img alt="" loading="lazy" src="${it.src}"><span class="film-play" aria-hidden="true">▶</span>`;b.setAttribute('aria-label',it.title);b.addEventListener('click',()=>{lightboxMode='model';openLightbox(0);});li.append(b);return li;})()]:[]),...m.gallery.map((src,i)=>{const li=document.createElement('li'),b=document.createElement('button');b.type='button';b.setAttribute('aria-label',`${t('galOpen')} ${i+1}`);const im=document.createElement('img');im.src=src;im.alt='';im.loading='lazy';im.addEventListener('error',()=>li.remove());b.append(im);b.addEventListener('click',()=>{lightboxMode='model';openLightbox(i+offset);});li.append(b);return li;}));
 let rel=CAT.filter(x=>x.fam===m.fam&&x.id!==m.id);$('#tr-related-fam').textContent=t('fam_'+m.fam);if(!rel.length){rel=CAT.filter(x=>x.fam!==m.fam).slice(0,3);$('#tr-related-fam').textContent=t('navProducts');}
 $('#tr-related').replaceChildren(...rel.slice(0,3).map(catCard));syncCmpBoxes();
}
$('#tr-request').addEventListener('click',()=>{if(trModel)requestModel(trModel);});
$('#tr-split').addEventListener('input',e=>$('#tr-stage').style.setProperty('--split',e.target.value+'%'));
if(has('#tr-stage')&&!prefersReduced){const s0=performance.now();const intro=now=>{const p=Math.min((now-s0)/1700,1),v=100-(100-56)*(1-Math.pow(1-p,3));$('#tr-split').value=String(v);$('#tr-stage').style.setProperty('--split',v+'%');if(p<1)requestAnimationFrame(intro);};requestAnimationFrame(intro);}
