/* Datasheet numbers and the download library (unique PDFs behind Maral's download links, with audit flags) */
const DOCS=typeof maralDocs!=='undefined'?maralDocs:[];
const ISSUE_FLAGS=['volume34','strayPage','tareMissing','volumeReefer'];
const dataValue=([,v,u])=>typeof v==='number'?`${nf(v)} ${u==='kg'?t('unitKg'):u==='mm'?t('unitMm'):u==='t'?t('unitT'):u==='L'?t('unitL'):u}`:`${v} ${u==='mm'?t('unitMm'):u}`;
const docTitle=d=>d.id==='catalogue'?t('dlCatTitle'):fillIn(t('dlSheetName'),{f:t('fam_'+CAT.find(m=>m.id===d.models[0])?.fam)});
const docMeta=d=>[fillIn(t('dlPages'),{n:nf(d.pages)}),`${nf(d.kb>1024?Math.round(d.kb/102.4)/10:d.kb,1)} ${d.kb>1024?'MB':'KB'}`,nf(d.year,0).replace(/[,٬\s]/g,''),t(d.lang==='en'?'dlLangEn':'dlLangFaEn')].join(' · ');
function renderDatasheet(m){
 const rows=m.data||[];$('#tr-data').hidden=!rows.length&&!m.doc;
 const get=k=>rows.find(r=>r[0]===k)?.[1],tare=get('tare'),pay=get('payload');
 $('#weight-bar').hidden=!(tare&&pay);
 if(tare&&pay){const gross=tare+pay;$('#wb-tare').style.width=(tare/gross*100)+'%';$('#wb-pay').style.width=(pay/gross*100)+'%';$('#wb-legend').innerHTML='';[['d_tare',tare],['d_payload',pay],['trGross',gross]].forEach(([k,v])=>{const s=document.createElement('span');s.innerHTML='<i></i><b></b><small></small>';s.querySelector('b').textContent=`${nf(v)} ${t('unitKg')}`;s.querySelector('small').textContent=t(k);$('#wb-legend').append(s);});}
 $('#data-grid').replaceChildren(...rows.filter(r=>!(tare&&pay&&['tare','payload'].includes(r[0]))).map(r=>{const d=document.createElement('div');d.innerHTML='<dt></dt><dd></dd>';d.firstChild.textContent=t('d_'+r[0]);d.lastChild.textContent=dataValue(r);return d;}));
 const doc=DOCS.find(d=>d.id===m.doc);$('#tr-doc').hidden=!doc;
 if(doc){$('#tr-doc').href=doc.url;$('#tr-doc-meta').textContent=docMeta(doc);const others=doc.models.filter(id=>id!==m.id).map(id=>CAT.find(x=>x.id===id)?.name[lang]).filter(Boolean);$('#tr-doc-flags').textContent=[others.length?fillIn(t('trDocShared'),{m:others.join('، ')}):'',...doc.flags.filter(f=>f!=='shared'&&!ISSUE_FLAGS.includes(f)).map(f=>t('flag_'+f))].filter(Boolean).join(' · ');}
}
function renderDownloads(){
 if(page!=='downloads'||!DOCS.length)return;
 const cat=DOCS.find(d=>d.id==='catalogue');$('#dl-cat-link').href=cat.url;$('#dl-cat-meta').textContent=docMeta(cat);
 $('#dl-cover').replaceChildren(...CAT.filter((m,i)=>i%3===0).slice(0,6).map(m=>{const im=document.createElement('img');im.src=m.drawing;im.alt='';im.loading='lazy';return im;}));
 $('#dl-grid').replaceChildren(...DOCS.filter(d=>d.id!=='catalogue').map(d=>{
  const first=CAT.find(m=>m.id===d.models[0]),li=document.createElement('li');li.className='dl-card';
  li.innerHTML=`<div class="dl-thumb"><img alt="" loading="lazy" src="${first.drawing}"><span class="doc-icon">PDF</span></div><div class="dl-body"><h3></h3><p class="dl-meta"></p><p class="dl-covers"><span class="dl-label"></span></p><ul class="dl-flags"></ul><a class="dl-btn" href="${d.url}" target="_blank" rel="noopener"><span></span> <i aria-hidden="true">↓</i></a></div>`;
  $('h3',li).textContent=docTitle(d);$('.dl-meta',li).textContent=docMeta(d);$('.dl-label',li).textContent=t('dlCovers');$('.dl-btn span',li).textContent=t('dlDownload');
  d.models.forEach(id=>{const m=CAT.find(x=>x.id===id),a=document.createElement('a');a.href='trailer.html?m='+id;a.textContent=m.name[lang];$('.dl-covers',li).append(a);});
  d.flags.filter(f=>!ISSUE_FLAGS.includes(f)&&f!=='shared').forEach(f=>{const fl=document.createElement('li');fl.className='info';fl.textContent=t('flag_'+f);$('.dl-flags',li).append(fl);});
  return li;}));
 const sheets=DOCS.filter(d=>d.id!=='catalogue'),pages=DOCS.reduce((a,d)=>a+d.pages,0),mb=DOCS.reduce((a,d)=>a+d.kb,0)/1024;
 const stats=[[21,'dlStatLinks'],[DOCS.length,'dlStatDocs'],[pages,'dlStatPages'],[sheets.filter(d=>d.flags.some(f=>ISSUE_FLAGS.includes(f))).length,'dlStatIssues']];
 $('#dl-stats').replaceChildren(...stats.map(([v,k])=>{const d=document.createElement('div');d.innerHTML='<dt></dt><dd></dd>';d.firstChild.textContent=t(k);d.lastChild.textContent=nf(v);return d;}));
 $('#dl-findings').replaceChildren(...['find1','find2','find3','find4','find5'].map(k=>{const li=document.createElement('li');li.textContent=fillIn(t(k),{mb:nf(mb,1)});return li;}));
}
