/* Knowledge base: Maral's own articles (EN + FA), re-shelved by topic, with a reader that links back to the catalogue */
const ARTS=typeof maralArticles!=='undefined'?maralArticles:[];
const TOPICS=['buying','axles','maintenance','standards','costs','maral','industry'];
const PATHS={buying:['buying'],axles:['axles'],maintenance:['maintenance','standards']};
let kbTopic=TOPICS.includes(params.get('topic'))?params.get('topic'):'all',kbQuery='',readerBody=null;
const artLang=()=>lang==='fa'?'fa':'en';
const artsForLang=()=>ARTS.filter(a=>a.lang===artLang());
function artCard(a){
 const li=document.createElement('li');li.className='kb-card';li.style.viewTransitionName=a.id;
 li.innerHTML=`<a href="article.html?a=${a.id}"><span class="kb-img"><img alt="" loading="lazy" referrerpolicy="no-referrer-when-downgrade" src="${a.img}"></span><span class="kb-card-copy"><span class="kb-tag"></span><b></b><span class="kb-desc"></span><span class="kb-foot"><span class="kb-read"></span><span class="kb-fams"></span></span></span></a>`;
 li.querySelector('a').lang=a.lang;li.querySelector('a').dir=a.lang==='fa'?'rtl':'ltr';
 $('.kb-tag',li).textContent=t('topic_'+a.topic);$('b',li).textContent=a.title;$('.kb-desc',li).textContent=a.desc;$('.kb-read',li).textContent=fillIn(t('kbMin'),{n:nf(a.min)});
 a.fams.forEach(f=>{const s=document.createElement('span');s.textContent=t('fam_'+f);$('.kb-fams',li).append(s);});
 $('img',li).addEventListener('error',e=>{e.target.parentNode.classList.add('noimg');e.target.remove();});
 return li;
}
function renderKb(){
 if(page!=='articles'||!ARTS.length)return;
 const list=artsForLang(),feat=list.find(a=>a.topic==='maral')||list[0];
 $('#kb-feature').href='article.html?a='+feat.id;$('#kb-feature-img').src=feat.img;$('#kb-feature-tag').textContent=t('topic_'+feat.topic);$('#kb-feature-title').textContent=feat.title;$('#kb-feature-title').dir=feat.lang==='fa'?'rtl':'ltr';$('#kb-feature-min').textContent=fillIn(t('kbMin'),{n:nf(feat.min)});
 const topics=TOPICS.filter(k=>list.some(a=>a.topic===k));
 $('#kb-stats').replaceChildren(...[[list.length,'kbStatArticles'],[topics.length,'kbStatTopics'],[list.reduce((n,a)=>n+a.min,0),'kbStatMinutes']].map(([v,k])=>{const d=document.createElement('div');d.innerHTML='<dt></dt><dd></dd>';d.firstChild.textContent=t(k);d.lastChild.textContent=nf(v);return d;}));
 $('#kb-lang-note').textContent=['ru','ar'].includes(lang)?t('kbLangNote'):'';
 $('#kb-paths').replaceChildren(...Object.entries(PATHS).map(([k,tps],i)=>{const d=document.createElement('div');d.className='kb-path';d.innerHTML=`<span class="kb-path-no">0${i+1}</span><h3></h3><p></p><ol></ol>`;$('h3',d).textContent=t('path_'+k);$('p',d).textContent=t('pathD_'+k);
  list.filter(a=>tps.includes(a.topic)).slice(0,4).forEach(a=>{const li=document.createElement('li'),l=document.createElement('a');l.href='article.html?a='+a.id;l.textContent=a.title;l.dir=a.lang==='fa'?'rtl':'ltr';li.append(l);$('ol',d).append(li);});return d;}));
 const bar=$('#kb-topics');bar.replaceChildren(...['all',...topics].map(k=>{const b=document.createElement('button');b.type='button';b.className='cat-fam-btn';b.setAttribute('aria-pressed',String(k===kbTopic));b.innerHTML=`<span></span><sup>${nf(k==='all'?list.length:list.filter(a=>a.topic===k).length)}</sup>`;b.firstChild.textContent=t(k==='all'?'galAll':'topic_'+k);b.addEventListener('click',()=>{const run=()=>{kbTopic=k;renderKb();};if(document.startViewTransition&&!prefersReduced)document.startViewTransition(run);else run();});return b;}));
 const q=kbQuery.trim().toLowerCase(),shown=list.filter(a=>(kbTopic==='all'||a.topic===kbTopic)&&(!q||(a.title+' '+a.desc+' '+a.heads.join(' ')).toLowerCase().includes(q)));
 $('#kb-grid').replaceChildren(...shown.map(artCard));$('#kb-empty').hidden=shown.length>0;$('#kb-search').placeholder=t('kbSearch');$('#kb-search').setAttribute('aria-label',t('kbSearch'));
}
$('#kb-search').addEventListener('input',e=>{kbQuery=e.target.value;renderKb();});
let tocObserver=null;
function renderReader(){
 if(page!=='article'||!ARTS.length)return;
 const a=ARTS.find(x=>x.id===params.get('a'))||artsForLang()[0],rd=$('#reader');
 rd.lang=a.lang;$('.rd-hero-copy').dir=a.lang==='fa'?'rtl':'ltr';$('#rd-body').dir=a.lang==='fa'?'rtl':'ltr';
 document.title=`${a.title} — MARAL`;$('#rd-img').src=a.img;$('#rd-title').textContent=a.title;$('#rd-desc').textContent=a.desc;
 $('#rd-meta').textContent=[t('topic_'+a.topic),fillIn(t('kbMin'),{n:nf(a.min)}),a.lang==='fa'?'فارسی':'English'].join(' · ');
 $('#rd-topic').textContent=t('topic_'+a.topic);$('#rd-topic').href=`articles.html?topic=${a.topic}#library`;$('#rd-source').href=a.src;
 const models=a.fams.map(f=>CAT.find(m=>m.fam===f)).filter(Boolean);$('#rd-models-box').hidden=!models.length;
 $('#rd-models').replaceChildren(...models.map(m=>{const li=document.createElement('li');li.innerHTML=`<a href="trailer.html?m=${m.id}"><span class="rd-model-img"><img alt="" src="${m.drawing}"></span><span><b></b><small></small></span></a>`;$('b',li).textContent=m.name[lang];$('small',li).textContent=m.code;return li;}));
 $('#rd-related').replaceChildren(...ARTS.filter(x=>x.lang===a.lang&&x.id!==a.id&&(x.topic===a.topic||x.fams.some(f=>a.fams.includes(f)))).slice(0,3).map(artCard));
 const fill=html=>{const body=$('#rd-body');body.innerHTML=html;const heads=$$('h2',body);heads.forEach((h,i)=>{h.id='s'+(i+1);});
  $('#rd-toc').replaceChildren(...heads.map(h=>{const li=document.createElement('li'),l=document.createElement('a');l.href='#'+h.id;l.textContent=h.textContent;li.append(l);return li;}));$('.rd-toc').hidden=heads.length<2;
  tocObserver?.disconnect();tocObserver=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)$$('#rd-toc a').forEach(l=>l.classList.toggle('on',l.hash==='#'+e.target.id));}),{rootMargin:'-20% 0px -70% 0px'});heads.forEach(h=>tocObserver.observe(h));};
 if(readerBody)fill(readerBody);
 else if(typeof fetch==='function')fetch(`articles/${a.id}.json`).then(r=>r.json()).then(j=>{readerBody=j.body;fill(readerBody);}).catch(()=>{$('#rd-body').textContent=t('rdError');});
}
/* FAQ: general questions plus per-model answers generated from the datasheet numbers */
const FAQ_GROUPS=[['buy',['g1','g2','g3']],['tech',['g4','g5','g6']],['service',['g7','g8','g9']],['export',['g10','g11','g12']]];
function faqList(items){const wrap=document.createElement('div');wrap.className='faq-list';items.forEach(([q,a])=>{const d=document.createElement('details');d.className='faq-item';d.innerHTML='<summary><span></span><i aria-hidden="true"></i></summary><div class="faq-a"></div>';$('summary span',d).textContent=q;$('.faq-a',d).textContent=a;wrap.append(d);});return wrap;}
function modelFaq(m){
 const row=k=>(m.data||[]).find(r=>r[0]===k),val=k=>row(k)?.[1],name=m.name[lang],pay=val('payload'),tare=val('tare'),vol=row('volume'),kp=val('kingpin');
 const cap=pay?[fillIn(t('mfACap'),{p:nf(pay)}),vol?fillIn(t('mfAVol'),{v:dataValue(vol)}):'',tare?fillIn(t('mfATare'),{t:nf(tare),g:nf(tare+pay)}):'',t('mfALegal')].filter(Boolean).join(' '):t('mfACapNone');
 const axles=m.figs.find(f=>f[0]==='axles')?.[1]||'3 × 9 t',special=['fuel','lpg','bitumen'].includes(m.id)?m.id:m.fam;
 return [[fillIn(t('mfQCap'),{m:name}),cap],[t('mfQTractor'),kp?fillIn(t('mfATractor'),{k:nf(kp)}):t('mfATractorGen')],[t('mfQBrakes'),fillIn(t('mfABrakes'),{a:figValue(axles)})],[t('mfQ_'+special),t('mfA_'+special)],[t('mfQWarranty'),t('mfAWarranty')]];
}
function renderModelFaq(){if(page==='trailer'&&trModel)$('#tr-faq').replaceChildren(faqList(modelFaq(trModel)));}
function renderFaq(){
 if(page!=='faq')return;
 $('#faq-nav').replaceChildren(...[...FAQ_GROUPS.map(([g])=>['faq-'+g,'faqGrp_'+g]),['faq-model-section','faqByModelEyebrow']].map(([id,k],i)=>{const a=document.createElement('a');a.href='#'+id;a.innerHTML=`<span>${fmt(i+1)}</span>`;a.append(t(k));return a;}));
 $('#faq-general').replaceChildren(...FAQ_GROUPS.map(([g,keys],i)=>{const sec=document.createElement('section');sec.className='faq-group';sec.id='faq-'+g;sec.innerHTML=`<p class="eyebrow dark"><span class="index">${fmt(i+1)}</span><span></span></p>`;$('.eyebrow span:last-child',sec).textContent=t('faqGrp_'+g);sec.append(faqList(keys.map(k=>[t('faqQ_'+k),t('faqA_'+k)])));return sec;}));
 const sel=$('#faq-model'),cur=sel.value||params.get('m')||'tipper-34';sel.replaceChildren(...CAT.map(m=>{const o=document.createElement('option');o.value=m.id;o.textContent=`${m.name[lang]} · ${m.code}`;return o;}));sel.value=CAT.some(m=>m.id===cur)?cur:CAT[0].id;
 const m=CAT.find(x=>x.id===sel.value);$('#faq-model-list').replaceChildren(faqList(modelFaq(m)));$('#faq-model-link').href='trailer.html?m='+m.id;$('#faq-model-link').textContent=t('faqOpenModel');
 $('#faq-review').replaceChildren(...['faqRev1','faqRev2','faqRev3','faqRev4','faqRev5'].map(k=>{const li=document.createElement('li');li.textContent=t(k);return li;}));
}
