function setDep(k){if(!DEP_ROUTE[k])k='sales';$('#ct-dep').value=k;$$('.dep-card').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.dep===k)));$('#ct-route-to').textContent=fillIn(t('ctRouteTo'),{d:t('dep_'+k),o:t(DEP_ROUTE[k])});}
$$('.dep-card').forEach(b=>b.addEventListener('click',()=>{setDep(b.dataset.dep);$('#ct-form-section').scrollIntoView({behavior:prefersReduced?'instant':'smooth',block:'start'});$('#ct-name').focus({preventScroll:true});}));
$('#ct-dep').addEventListener('change',e=>setDep(e.target.value));
$('#ct-form').addEventListener('submit',e=>{e.preventDefault();if(!$('#ct-form').reportValidity())return;const d=new Date(),ref='MRL-C-'+d.toISOString().slice(2,10).replace(/-/g,'')+'-'+Math.random().toString(36).slice(2,5).toUpperCase();$('#ct-done').hidden=false;$('#ct-done-text').textContent=fillIn(t('ctDoneText'),{r:ref,d:t('dep_'+$('#ct-dep').value)});});
function renderContact(){if(page==='contact')setDep($('#ct-dep').value||params.get('dep')||'sales');}
